'VFRequest r={0,0,0,0};CHECK(vf_request(&r,0));CHECK(vf_request(&r,1));CHECK(!vf_request(&r,3));CHECK(vf_request(&r,2));CHECK(vf_request(&r,3));CHECK(!vf_request(&r,3));',
